CREATE TABLE "types" (
    "a"         INTEGER,
    "b"         INTEGER,
    "c"         INTEGER,
    "d"         SMALLINT,
    "e"         BIGINT,
    "f"         BOOLEAN,
    "g"         BOOLEAN,
    "h"         VARCHAR(255),
    "i"         VARCHAR,
    "j"         CHAR(3),
    "k"         NUMERIC,
    "l"         NUMERIC(10, 2),
    "m"         TIMESTAMP,
    "n"         TIMESTAMPTZ(3),
    "o"         TIMETZ,
    "p"         DOUBLE PRECISION,
    "q"         REAL,
    "r"         DOUBLE PRECISION,
    "s"         UUID,
    "t"         JSONB,
    "u"         TEXT[],
    "v"         INTEGER[3],
    "w"         "MyType",
    "x"         BPCHAR,
    "y"         TEXT                DEFAULT E'line1\nline2',
    "z"         TEXT                DEFAULT 'it''s',
    "aa"        TEXT                DEFAULT 'a\b',
    "bb"        INTEGER             DEFAULT -1,
    "cc"        INTEGER             DEFAULT (1 + 2) * 3,
    "dd"        BOOLEAN             DEFAULT (NOT (TRUE AND FALSE)),
    "ee"        TEXT                DEFAULT 'x' || 'y',
    "ff"        INTEGER             DEFAULT -(1 + 2),
    "gg"        TIMESTAMPTZ         DEFAULT CURRENT_TIMESTAMP,
    "hh"        TIMESTAMPTZ         DEFAULT ('2026-01-01'::TIMESTAMPTZ AT TIME ZONE 'UTC'),
    "ii"        NUMERIC             DEFAULT 1.5,
    "jj"        INTEGER             DEFAULT COALESCE(NULL, 1),
    "kk"        TEXT COLLATE "C"    DEFAULT 1::TEXT,
    "UserId"    INTEGER,
    "userid"    INTEGER
);
